INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Backup-Systeme eine technische Maßnahme für IT-Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Schützen vor Datenverlust"}, {"text": "Nein", "correct": false, "because": "Sie sind essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgen Backup-Systeme?', 3, '[{"text": "Datenwiederherstellung nach Verlust", "correct": true, "because": "Sichert Verfügbarkeit"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Daten löschen", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Backup-Systeme schützen vor Datenverlust. b) Sie verhindern Cyberangriffe.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, nur Wiederherstellung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Backup-Systemen gibt es?', 4, '[{"text": "Vollbackup", "correct": true, "because": "Komplette Daten"}, {"text": "Unklare Typen", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Inkrementelles Backup", "correct": true, "because": "Nur Änderungen"}, {"text": "Differentielles Backup", "correct": true, "because": "Änderungen seit Vollbackup"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Unternehmen ohne Backup-Systeme sicher arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Datenverlust riskant"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen Backup-Systeme im Datenschutz?', 3, '[{"text": "Sichern Daten gegen Verlust", "correct": true, "because": "Fördert Verfügbarkeit"}, {"text": "Identität prüfen", "correct": false, "because": "Authentizität"}, {"text": "Daten manipulieren", "correct": false, "because": "Integrität"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Backup-Systeme nur für große Unternehmen relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch kleine Betriebe"}, {"text": "Ja", "correct": false, "because": "Universelle Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Vollbackup?', 3, '[{"text": "Alle Daten sichern", "correct": true, "because": "Komplette Kopie"}, {"text": "Nur Änderungen sichern", "correct": false, "because": "Inkrementell"}, {"text": "Netzwerk konfigurieren", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Backups schützen vor Ransomware. b) Sie sind nur für Hardwarefehler wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, auch Software"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert ohne Backup-Systeme?', 3, '[{"text": "Datenverlust nicht wiederherstellbar", "correct": true, "because": "Keine Sicherung"}, {"text": "Daten schneller", "correct": false, "because": "Unsinn"}, {"text": "Systeme sicherer", "correct": false, "because": "Gegenteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Backup-System ohne Speichermedium arbeiten?', 2, '[{"text": "Nein", "correct": true, "because": "Speicher nötig"}, {"text": "Ja", "correct": false, "because": "Unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Beispiel zeigt ein Backup-System?', 3, '[{"text": "Tägliches Backup auf externe Festplatte", "correct": true, "because": "Konkret und real"}, {"text": "Daten löschen", "correct": false, "because": "Gegenteil"}, {"text": "Netzwerk trennen", "correct": false, "because": "Andere Maßnahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist ein Backup-System nur für Datenbanken relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Dateien, Systeme"}, {"text": "Ja", "correct": false, "because": "Breite Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat ein gutes Backup-System?', 4, '[{"text": "Regelmäßigkeit", "correct": true, "because": "Aktuelle Daten"}, {"text": "Unklare Speicherung", "correct": false, "because": "Widerspricht Klarheit"}, {"text": "Sicherer Speicherort", "correct": true, "because": "Schützt Backups"}, {"text": "Wiederherstellbarkeit", "correct": true, "because": "Nutzen bei Verlust"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Backup-System verschlüsselt sein?', 2, '[{"text": "Nein", "correct": true, "because": "Optional"}, {"text": "Ja", "correct": false, "because": "Empfohlen, nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt ein inkrementelles Backup?', 3, '[{"text": "Nur Änderungen sichern", "correct": true, "because": "Effiziente Speicherung"}, {"text": "Daten verschlüsseln", "correct": false, "because": "Andere Maßnahme"}, {"text": "Netzwerk verbinden", "correct": false, "because": "Kein Zusammenhang"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Backup-System ohne Planung betrieben werden?', 2, '[{"text": "Ja", "correct": true, "because": "Aber ineffizient"}, {"text": "Nein", "correct": false, "because": "Planung verbessert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst Backup-Systeme?', 3, '[{"text": "Datenmenge", "correct": true, "because": "Bestimmt Speicherbedarf"}, {"text": "Monitorgröße", "correct": false, "because": "Irrelevant"}, {"text": "Tastaturlayout", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Backup-Systeme sind Teil des Datenschutzes. b) Sie schützen vor Identitätsdiebstahl.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Authentizität"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist nicht korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist zutreffend"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist ein Nutzen von Backup-Systemen?', 3, '[{"text": "Datensicherung bei Ausfall", "correct": true, "because": "Fördert Wiederherstellung"}, {"text": "Maximale Datenverluste", "correct": false, "because": "Widerspricht Zweck"}, {"text": "Keine Wiederherstellung", "correct": false, "because": "Fördert Verfügbarkeit"}]');
